import { ImageAsset, Node, Rect, Size, resources, Sprite, SpriteFrame, Texture2D, UITransform, UIOpacity } from 'cc';

type Kind='drop'|'collision'|'merge'|'combo'|'danger'|'result'|'tap';
type Atlas={texture:Texture2D;frames:SpriteFrame[];fps:number};
type Active={node:Node;kind:Kind;age:number;atlas:Atlas;owner:string};
const atlasFor:Record<Kind,string>={drop:'contact_spark',collision:'contact_spark',merge:'merge_burst',combo:'combo_star',danger:'danger_glow',result:'settle_stars',tap:'tap_ring'};
const frameCounts:Record<string,number>={contact_spark:12,merge_burst:16,combo_star:12,danger_glow:12,settle_stars:16,tap_ring:12};
const cap:Record<Kind,number>={drop:8,collision:8,merge:5,combo:2,danger:1,result:1,tap:8};

/** Cosmetic-only frame atlas player. Its nodes are siblings of game art, never physics bodies. */
export class EffectsController {
  private atlases=new Map<string,Atlas>();private active:Active[]=[];private generation=1;private paused=false;private disposed=false;private reducedMotion=false;
  private loading=new Map<string,Promise<Atlas|null>>();private catImage:ImageAsset|null=null;private catTexture:Texture2D|null=null;private catTime=0;private catNode:Node|null=null;private catX=0;private catY=0;private catRequested=false;
  constructor(private readonly root:Node){}
  setReducedMotion(value:boolean):void{this.reducedMotion=value;}
  setPaused(value:boolean):void{this.paused=value;}
  async prepare():Promise<void>{for(const key of ['contact_spark','merge_burst','combo_star','danger_glow','settle_stars','tap_ring'])await this.load(key);}
  update(dt:number):void{if(this.disposed||this.paused||!Number.isFinite(dt)||dt<=0)return;this.catTime+=dt;if(this.catNode?.isValid)this.catNode.setPosition(this.catX,this.catY+Math.sin(this.catTime*2.4)*3,0);for(let i=this.active.length-1;i>=0;i--){const a=this.active[i];if(!a.node.isValid){this.active.splice(i,1);continue;}a.age+=dt;const frame=Math.min(a.atlas.frames.length-1,Math.floor(a.age*a.atlas.fps));const sprite=a.node.getComponent(Sprite);if(sprite)sprite.spriteFrame=a.atlas.frames[frame];const op=a.node.getComponent(UIOpacity);if(op&&a.age>a.atlas.frames.length/a.atlas.fps*.72)op.opacity=Math.max(0,Math.round(255*(1-(a.age-a.atlas.frames.length/a.atlas.fps*.72)/(a.atlas.frames.length/a.atlas.fps*.28))));if(frame>=a.atlas.frames.length-1){a.node.destroy();this.active.splice(i,1);}}}
  async play(kind:Kind,x:number,y:number,owner:string,reduced=this.reducedMotion):Promise<void>{if(this.disposed||this.paused||reduced&&kind!=='danger')return;const generation=this.generation,name=atlasFor[kind],atlas=await this.load(name);if(!atlas||this.disposed||this.paused||generation!==this.generation||!this.root.isValid)return;const same=this.active.filter(a=>a.kind===kind);if(same.length>=cap[kind]){const oldest=same[0];oldest.node.destroy();this.active=this.active.filter(a=>a!==oldest);}const n=new Node(`V2FX-${kind}`);this.root.addChild(n);n.setPosition(x-375,y-667,0);n.addComponent(UITransform).setContentSize(kind==='danger'?92:kind==='result'?220:kind==='tap'?68:112,kind==='danger'?92:kind==='result'?220:kind==='tap'?68:112);n.addComponent(Sprite).spriteFrame=atlas.frames[0];n.addComponent(UIOpacity).opacity=255;this.active.push({node:n,kind,age:0,atlas,owner});}
  ensureCat(x:number,y:number):void{if(this.disposed)return;this.catRequested=true;this.catX=x-375;this.catY=y-667;if(this.catNode?.isValid){this.catNode.setPosition(this.catX,this.catY,0);return;}if(this.catImage){this.makeCat();return;}resources.load('effects/v2/cat_barista',ImageAsset,(error,image)=>{if(error||!image||this.disposed||!this.catRequested)return;this.catImage=image;this.catTexture=new Texture2D();this.catTexture.image=image;this.makeCat();});}
  hideCat():void{this.catRequested=false;if(this.catNode?.isValid)this.catNode.destroy();this.catNode=null;}
  private makeCat():void{if(!this.catImage||!this.catTexture||!this.root.isValid)return;this.catNode=new Node('V2CatBarista');this.root.addChild(this.catNode);this.catNode.setPosition(this.catX,this.catY,0);this.catNode.addComponent(UITransform).setContentSize(92,110);const frame=new SpriteFrame();frame.reset({texture:this.catTexture,rect:new Rect(0,0,this.catImage.width,this.catImage.height),originalSize:new Size(this.catImage.width,this.catImage.height)});const sprite=this.catNode.addComponent(Sprite);sprite.sizeMode=Sprite.SizeMode.CUSTOM;sprite.trim=false;sprite.spriteFrame=frame;this.catNode.getComponent(UITransform)!.setContentSize(92,110);}
  cancelOwner(owner:string):void{for(const a of this.active.filter(v=>v.owner===owner)){a.node.destroy();this.active.splice(this.active.indexOf(a),1);}}
  dispose():void{this.disposed=true;this.generation++;for(const a of this.active)a.node.destroy();this.active=[];for(const atlas of this.atlases.values()){for(const frame of atlas.frames)frame.destroy();atlas.texture.destroy();}this.atlases.clear();if(this.catNode?.isValid)this.catNode.destroy();this.catNode=null;this.catTexture?.destroy();this.catTexture=null;this.catImage=null;}
  private async load(name:string):Promise<Atlas|null>{const cached=this.atlases.get(name);if(cached)return cached;const pending=this.loading.get(name);if(pending)return pending;const generation=this.generation;const task=new Promise<Atlas|null>(resolve=>{const done=(error:unknown,image:ImageAsset|null):void=>{if(error||!image||this.disposed||generation!==this.generation){resolve(null);return;}const texture=new Texture2D();texture.image=image;const frames:SpriteFrame[]=[];for(let i=0;i<frameCounts[name];i++){const frame=new SpriteFrame();frame.reset({texture,rect:new Rect((i%4)*(image.width/4),Math.floor(i/4)*(image.width/4),image.width/4,image.width/4),originalSize:new Size(image.width/4,image.width/4)});frames.push(frame);}const atlas={texture,frames,fps:24};this.atlases.set(name,atlas);resolve(atlas);};
      // Project resource loader is intentionally best effort; missing effects never gate gameplay.
      resources.load(`effects/v2/${name}_sheet_4col`,ImageAsset,done);
    });this.loading.set(name,task);void task.then(()=>{if(this.loading.get(name)===task)this.loading.delete(name);},()=>{if(this.loading.get(name)===task)this.loading.delete(name);});return task;}
}
